import math, pickle, os
from collections import Counter

CT = "SALKMSKXZYRZEJFEOTMBRRZBRXYCXPNJIIWDRYADAIWKKKBEBUDDGNCXTUUBSJXMQVIVPVBYQEVVRBXMTEFGHRVULFEJZZUTXZIVBABSKQESEWKPKGXNVGTZHIFVWLCAQDHOKIGZZRV"
_dir = os.path.dirname(os.path.abspath(__file__))
with open(os.path.join(_dir,'quads.pkl'),'rb') as f: QUAD = pickle.load(f)
TOT = sum(QUAD.values())
def quad_score(s):
    if len(s) < 4: return -99
    return sum(math.log10((QUAD.get(s[i:i+4],0)+0.01)/TOT) for i in range(len(s)-3))/(len(s)-3)

SQ = "ABCDEFGHIKLMNOPQRSTUVWXYZ"  # 5x5, J->I
def bifid_dec(ct, period):
    coords = {}
    for i,ch in enumerate(SQ): coords[ch]=(i//5,i%5)
    def to_pairs(s):
        out=[]
        for c in s:
            c = 'I' if c=='J' else c
            out.append(coords.get(c))
        return out
    P = to_pairs(ct)
    n = len(ct)
    out=[]
    for start in range(0, n, period):
        block = P[start:start+period]
        rows = [r for r,_ in block]
        cols = [c for _,c in block]
        flat = rows+cols
        for k in range(0, len(flat)-1, 2):
            out.append(SQ[flat[k]*5+flat[k+1]])
    return ''.join(out)

print("=== BIFID (standard square) ===")
res=[]
for period in list(range(2,25)) + [n if (n:=len(CT)) else 0]:
    p = bifid_dec(CT, period)
    res.append((quad_score(p), period, p))
res.sort(reverse=True)
for s,per,p in res[:6]:
    print(f"{s:7.4f} period={per:3d} {p[:60]}")

print("=== TRIFID (3x3x3, 27 = A-Z + '#') ===")
T3 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ#"
def trifid_dec(ct, period):
    coords = {}
    for i,ch in enumerate(T3):
        coords[ch] = (i//9, (i%9)//3, i%3)
    n=len(ct); out=[]
    C=[('I' if c=='J' else c) for c in ct]
    P=[coords.get(c) for c in C]
    for start in range(0,n,period):
        block=P[start:start+period]
        f=[v for tup in block for v in tup]
        for k in range(0,len(f)-2,3):
            a,b,c = f[k],f[k+1],f[k+2]
            idx = a*9+b*3+c
            out.append(T3[idx])
    return ''.join(out)
res=[]
for period in list(range(2,25)) + [len(CT)]:
    p = trifid_dec(CT, period)
    res.append((quad_score(p), period, p))
res.sort(reverse=True)
for s,per,p in res[:6]:
    print(f"{s:7.4f} period={per:3d} {p[:60]}")

print("=== PLAYFAIR (standard square) ===")
def playfair_dec(ct, sq):
    pos = {ch:i for i,ch in enumerate(sq)}
    out=[]
    s = ct.replace('J','I')
    i=0
    while i < len(s):
        a,b = s[i], s[i+1] if i+1<len(s) else 'X'
        ra,ca = divmod(pos[a],5); rb,cb = divmod(pos[b],5)
        if ra==rb:
            out.append(sq[ra*5+(ca-1)%5]); out.append(sq[rb*5+(cb-1)%5])
        elif ca==cb:
            out.append(sq[((ra-1)%5)*5+ca]); out.append(sq[((rb-1)%5)*5+cb])
        else:
            out.append(sq[ra*5+cb]); out.append(sq[rb*5+ca])
        i+=2
    return ''.join(out)
p = playfair_dec(CT, SQ)
print(f"{quad_score(p):7.4f} {p[:60]}")

print("=== columnar transposition sanity (should not fit flat IC) ===")

import math, pickle, os, random
_dir = os.path.dirname(os.path.abspath(__file__))
with open(os.path.join(_dir,'quads.pkl'),'rb') as f: QUAD = pickle.load(f)
TOT = sum(QUAD.values())
def score(s):
    return sum(math.log10((QUAD.get(s[i:i+4],0)+0.01)/TOT) for i in range(len(s)-3))/(len(s)-3)

CT = "SALKMSKXZYRZEJFEOTMBRRZBRXYCXPNJIIWDRYADAIWKKKBEBUDDGNCXTUUBSJXMQVIVPVBYQEVVRBXMTEFGHRVULFEJZZUTXZIVBABSKQESEWKPKGXNVGTZHIFVWLCAQDHOKIGZZRV"
N = len(CT)

def bifid_dec(ct, sq, period):
    pos = {ch:i for i,ch in enumerate(sq)}
    out=[]
    rows=[]; cols=[]
    for c in ct:
        r,cn = divmod(pos[c],5)
        rows.append(r); cols.append(cn)
