_dir = os.path.dirname(os.path.abspath(__file__))
with open(os.path.join(_dir,'quads.pkl'),'rb') as f: QUAD = pickle.load(f)
TOT = sum(QUAD.values())
def score(s):
    return sum(math.log10((QUAD.get(s[i:i+4],0)+0.01)/TOT) for i in range(len(s)-3))/(len(s)-3)

CT = "SALKMSKXZYRZEJFEOTMBRRZBRXYCXPNJIIWDRYADAIWKKKBEBUDDGNCXTUUBSJXMQVIVPVBYQEVVRBXMTEFGHRVULFEJZZUTXZIVBABSKQESEWKPKGXNVGTZHIFVWLCAQDHOKIGZZRV"
N = len(CT)

def bifid_dec(ct, sq, period):
    pos = {ch:i for i,ch in enumerate(sq)}
    out=[]
    rows=[]; cols=[]
    for c in ct:
        r,cn = divmod(pos[c],5)
        rows.append(r); cols.append(cn)
    flat = rows+cols
    for start in range(0, N, period):
        blk = flat[2*start:2*start+2*period]
        for k in range(0, len(blk)-1, 2):
            out.append(sq[blk[k]*5+blk[k+1]])
    return ''.join(out)

def solve_period(period, restarts=14, seed0=0):
    rnd = random.Random(seed0*97+period)
    results=[]
    for r in range(restarts):
        sq = list("ABCDEFGHIKLMNOPQRSTUVWXYZ")
        rnd.shuffle(sq); sq=''.join(sq)
        cur = score(bifid_dec(CT, sq, period))
        improved=True
        while improved:
            improved=False
            best=None
            for i in range(25):
                for j in range(i+1,25):
                    s2 = list(sq); s2[i],s2[j] = s2[j],s2[i]
                    sc = score(bifid_dec(CT, ''.join(s2), period))
                    if sc > cur+1e-9:
                        cur = sc; best=''.join(s2); improved=True
                        break
            if best: sq = best
        results.append((cur, sq, bifid_dec(CT, sq, period)))
    results.sort(reverse=True)
    return results[0]

allres=[]
for period in range(2,26):
    s, sq, p = solve_period(period, restarts=14, seed0=1)
    allres.append((s, period, sq, p))
