def transforms(ct):
    yield "id", ct
    yield "rev", ct[::-1]
    yield "triom", ''.join(ct[i:i+3][::-1] for i in range(0,len(ct),3))
    for perm in ((0,1,2),(2,1,0),(1,0,2),(0,2,1),(1,2,0),(2,0,1)):
        ss=[ct[i::3][::-1] for i in range(3)]
        ss=[ss[p] for p in perm]
        out=[]; idx=[0,0,0]; k=0
        while any(idx[j]<len(ss[j]) for j in range(3)):
            j=k%3
            if idx[j]<len(ss[j]): out.append(ss[j][idx[j]]); idx[j]+=1
            k+=1
        yield f"streams{perm}", ''.join(out)
    cols=[ct[i::3] for i in range(3)]
    yield "col3", ''.join(''.join(c) for c in cols)
    yield "col3rev", ''.join(''.join(c[::-1]) for c in cols)
    # trio stream rotate: rotate each trio
    yield "triorot1", ''.join(ct[i+1]+ct[i+2]+ct[i] for i in range(0,len(ct)-2,3))
